<?php
use EIPSI\StudyEngine\Longitudinal as L;
use EIPSI\StudyEngine\Persistence as P;
function pf_initial_v1(){ $c=L\InitialScreen::defaults();$c['contract']='INITIAL_SCREEN_V1';$c['authentication']['confirm_after_first']=false;return $c;}
/** New versioned contract; all mail is captured by the disposable harness. */
pf_case('Initial screen validates and sanitizes rich text and styles',function(){
 $c=pf_initial_v1();$c['description_html']='<p><strong>Texto</strong><script>alert(1)</script><img src="javascript:x" onerror="alert(1)"></p>';$clean=L\InitialScreen::normalize($c);pe_assert(strpos($clean['description_html'],'<strong>Texto</strong>')!==false&&strpos($clean['description_html'],'<script')===false&&strpos($clean['description_html'],'onerror')===false,'Unsafe rich text');
 $c['background']='red;position:fixed';pe_reject(function()use($c){L\InitialScreen::normalize($c);},'INVALID_INITIAL_COLOR');
});
pf_case('Rich email label is sanitized and hiding retains an accessible name without changing authentication',function(){
 $c=L\InitialScreen::defaults();$c['authentication']['label_html']='<p><strong>Tu correo &amp; contacto</strong><script src="https://example.invalid/x.js"></script></p>';$c=L\InitialScreen::normalize($c);pe_assert(strpos($c['authentication']['label_html'],'<script')===false,'Unsafe label');$p=pf_publish(null,array('initial_screen'=>$c));$html=(new L\EmailTemplate())->screen(pf_runtime()->handle($p['public']));pe_assert(strpos($html,'<strong>Tu correo &amp; contacto</strong>')!==false&&strpos($html,'aria-labelledby="study-email-label"')!==false,'Rich label not associated');$c['authentication']['label_visible']=false;$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_runtime()->handle($p['public']);$html=(new L\EmailTemplate())->screen($f);pe_assert(strpos($html,'id="study-email-label"')===false&&strpos($html,'aria-label="Tu correo &amp; contacto"')!==false,'Hidden label inaccessible');$enrolled=pf_enroll($p);pe_assert($enrolled['view']['next_action']['kind']==='OPEN_ASSESSMENT','Hiding label changed access');
});
pf_case('Historical email labels remain visible without optional presentation fields',function(){
 $c=pf_initial_v1();unset($c['authentication']['label_html'],$c['authentication']['label_visible']);$before=$c;$normalized=L\InitialScreen::normalize($c);pe_equal($before,$normalized,'Legacy definition rewritten');$p=pf_publish(null,array('initial_screen'=>$c));$html=(new L\EmailTemplate())->screen(pf_runtime()->handle($p['public']));pe_assert(strpos($html,'id="study-email-label"')!==false&&strpos($html,'aria-labelledby="study-email-label"')!==false,'Legacy label hidden');$c['authentication']['label_visible']='false';pe_reject(function()use($c){L\InitialScreen::normalize($c);},'INVALID_AUTHENTICATION');
});
pf_case('Initial screen is presented before enrollment with abandonment and optional membership',function(){
 $c=pf_initial_v1();$c['authentication']['membership_enabled']=true;$c['title_html']='';$c['description_html']='<p>Descripción propia</p>';$c['withdrawal']['position']='TOP';$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_runtime()->handle($p['public']);$html=(new L\EmailTemplate())->screen($f);pe_assert(strpos($html,'Descripción propia')!==false&&strpos($html,'name="membership"')!==false&&strpos($html,'data-open-withdrawal')<strpos($html,'id="study-email"')&&strpos($html,'<dialog')!==false,'Initial composition');
});
pf_case('Membership existing checked never creates unknown participant',function(){
 $c=pf_initial_v1();$c['authentication']['membership_enabled']=true;$p=pf_publish(null,array('initial_screen'=>$c));$e=pf_runtime()->handle($p['public']);$r=array('action'=>'enroll','command_id'=>'MEMBER_MISSING','csrf'=>$e['csrf'],'email'=>'missing-member@example.test','membership'=>'1');$f=pf_runtime()->handle($p['public'],$e['token'],$r);pe_assert(isset($f['entry'])&&strpos($f['message'],'No encontramos')!==false,'Missing message');pe_assert((new L\Identity(pf_db(),pf_clock()))->byEmail($p['definition']['study']['logical_id'],$r['email'])===null,'Unexpected enrollment');
});
pf_case('Membership existing unchecked explains recovery without duplicating or exposing answers',function(){
 $c=pf_initial_v1();$c['authentication']['membership_enabled']=true;$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_enroll($p,'member@example.test');$e=pf_runtime()->handle($p['public']);$r=array('action'=>'enroll','command_id'=>'MEMBER_EXISTS','csrf'=>$e['csrf'],'email'=>'MEMBER@EXAMPLE.TEST','membership'=>'0');$reply=pf_runtime()->handle($p['public'],$e['token'],$r);pe_assert(isset($reply['entry'])&&strpos($reply['message'],'ya está registrado')!==false&&!isset($reply['access']),'Unsafe recovery');pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===1,'No recovery intent');
});
pf_case('Immediate verification gates first assessment and scientific POST until email link',function(){
 $c=pf_initial_v1();$c['authentication']['verification']='IMMEDIATE';$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED','No gate');$before=pf_owner()->view($f['access']['execution_id']);$reply=pf_runtime()->handle($p['public'],$f['token'],array('action'=>'submit','command_id'=>'GATED_SUBMIT','csrf'=>$f['csrf'],'expected_revision'=>$before['revision']));pe_assert($reply['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED'&&pf_owner()->view($f['access']['execution_id'])['revision']===$before['revision'],'Gate bypass');$r=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Access link not verification');
});
pf_case('Second-opportunity verification waits for completion and gates next scheduled assessment',function(){
 $saved=$GLOBALS['pf_now'];try{$c=pf_initial_v1();$c['authentication']['verification']='AFTER_FIRST';$p=pf_publish('03',array('initial_screen'=>$c,'provisional_hours'=>72));$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='OPEN_ASSESSMENT','First gated');$id=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$id,'responses'=>array('Q_PRE_1'=>3,'Q_PRE_2'=>3)));$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+86400);$r=pf_runtime()->handle($p['public'],$f['token']);pe_assert($r['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED','Second not gated');$r=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));pe_assert($r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Verified second unavailable');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('Verification-required opportunities enqueue independently even when notices disabled',function(){
 $c=pf_initial_v1();$c['authentication']['verification']='IMMEDIATE';$p=pf_publish('04',array('initial_screen'=>$c,'email_enabled'=>false));$f=pf_enroll($p);$rows=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($rows)===7&&count(array_unique(array_column($rows,'block_execution_id')))===7,'Not per opportunity');pe_assert(count(pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE'))===0,'Notices enabled');pf_runtime()->handle($p['public'],$f['token']);pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===7,'Refresh duplicates');
});
pf_case('Assessment and reminder links verify new contract and open current work',function(){
 foreach(array('ASSESSMENT_AVAILABLE','ASSESSMENT_REMINDER') as $purpose){$p=pf_publish(null,array('initial_screen'=>pf_initial_v1(),'verification_policy'=>'ALLOW_UNVERIFIED'));$f=pf_enroll($p);$r=pf_runtime()->redeem($p['public'],pf_mint($f,$purpose,$f['view']['next_action']['payload']['assessment_execution_id']));pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Not verified '.$purpose);}
});
pf_case('Removed withdrawal email command cannot enroll or queue mail',function(){
 $p=pf_publish(null,array('initial_screen'=>pf_initial_v1()));$e=pf_runtime()->handle($p['public']);$req=array('action'=>'withdrawal_access','command_id'=>'WITHDRAW_REMOVED','csrf'=>$e['csrf'],'email'=>'unknown-withdraw@example.test');pe_reject(function()use($p,$e,$req){pf_runtime()->handle($p['public'],$e['token'],$req);},'ACCESS_REQUIRED');pe_assert((new L\Identity(pf_db(),pf_clock()))->byEmail($p['definition']['study']['logical_id'],$req['email'])===null,'Removed command enrolled');$f=pf_enroll($p);$view=pf_owner()->view($f['access']['execution_id']);pe_reject(function()use($f,$view){(new L\NotificationScheduler(pf_db()))->authentication($f['access']['execution_id'],'WITHDRAWAL_OPTIONS','REMOVED',$view['snapshot']);},'INVALID_AUTHENTICATION_INTENT');pe_assert(pf_intents($f['access']['execution_id'],'WITHDRAWAL_OPTIONS')===array(),'Removed mail queued');
});
pf_case('Custom email templates interpolate safely without adding access or abandonment text',function(){
 $c=pf_initial_v1();$c['templates']['VERIFY_PARTICIPANT']=array('subject'=>'Verificá {{study_name}}','html'=>'<p><strong>{{study_name}}</strong></p><a href="{{direct_link}}">Entrar</a>');$c=L\InitialScreen::normalize($c);$v=array('study_name'=>'<script>alert(1)</script>','assessment_name'=>'','available_time'=>'','due_time'=>'','direct_link'=>'https://example.test/access','communications_link'=>'https://example.test/comms','withdrawal_link'=>'https://example.test/withdraw');$m=(new L\EmailTemplate())->render('VERIFY_PARTICIPANT',$v,$c['templates']);pe_assert(strpos($m['html'],'<script>')===false&&strpos($m['html'],'https://example.test/access')!==false&&strpos($m['html'],'Abandonar estudio')===false&&strpos($m['html'],'Administrar comunicaciones')===false&&substr_count($m['html'],'<a ' )===1,'Template unsafe or extra content');$c['templates']['VERIFY_PARTICIPANT']['html']='{{unknown}}';pe_reject(function()use($c){L\InitialScreen::normalize($c);},'UNKNOWN_TEMPLATE_VARIABLE');
});
pf_case('Legacy published participation can be confirmed with the validation email',function(){
 $p=pf_publish();$f=pf_enroll($p);$r=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&!isset($r['definition']['protocol_metadata']['longitudinal']['initial_screen']),'Verification did not confirm legacy participation');
});
pf_case('Native assessment endpoint enforces immediate verification independently of portal',function(){
 require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Store.php';require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/runtime/Authorization.php';
 $savedNow=$GLOBALS['pf_now'];$GLOBALS['pf_now']=(new L\Clock())->now();$c=pf_initial_v1();$c['authentication']['verification']='IMMEDIATE';$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_enroll($p);$name=L\Identity::cookieName($p['public']);$old=$_COOKIE[$name]??null;$_COOKIE[$name]=$f['token'];try{$binding=array('kind'=>'STUDY_SESSION','public_id'=>$p['public'],'execution_id'=>$f['access']['execution_id'],'participant_id'=>$f['access']['participant_id'],'study_version_id'=>$f['access']['study_version_id']);pe_reject(function()use($binding){pf_db()->transactional(function()use($binding){EIPSI\AssessmentEditor\Runtime\Authorization::check(new EIPSI\AssessmentEditor\Runtime\Store(),$binding);});},'Confirmá tu email');}finally{$GLOBALS['pf_now']=$savedNow;if($old===null)unset($_COOKIE[$name]);else $_COOKIE[$name]=$old;}
});
function pi_confirmation($fixture='03',$mode='NEVER'){
 $c=pf_initial_v1();$c['authentication']['confirm_after_first']=true;$c['authentication']['verification']=$mode;$p=pf_publish($fixture,array('initial_screen'=>$c,'provisional_hours'=>72));$f=pf_enroll($p);$id=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$id,'responses'=>$fixture===null?array('Q_q1'=>'Primera respuesta'):array('Q_PRE_1'=>3,'Q_PRE_2'=>3)));return array($p,pf_runtime()->handle($p['public'],$f['token']),$id);
}
function pi_request($p,$f,$email,$id=null){return pf_runtime()->handle($p['public'],$f['token'],array('action'=>'confirm_email','command_id'=>$id??'CONFIRM_'.bin2hex(random_bytes(8)),'csrf'=>$f['csrf'],'expected_revision'=>$f['view']['revision'],'email'=>$email,'confirm_email_change'=>'1'));}
function pi_mail_cap($f){$state=L\EmailConfirmation::read(pf_db(),$f['access']['execution_id']);$intent=pf_db()->row(pf_db()->prepare('SELECT * FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$state['intent_id']));pe_assert(pf_delivery($intent)['success'],'Confirmation mail failed');return pf_link(end($GLOBALS['m0_mail']));}
pf_case('Confirmation after first is independently required without authentication verification',function(){
 list($p,$f,$first)=pi_confirmation();pe_assert($f['view']['next_action']['kind']==='EMAIL_CONFIRMATION_REQUIRED','No confirmation step');$html=(new L\EmailTemplate())->screen($f);pe_assert(strpos($html,'primera evaluación quedó guardada')!==false&&strpos($html,'name="email"')!==false,'No correction field');pe_assert(pf_participant($f)['verification_state']==='UNVERIFIED','Implicit verification');$initial=pf_runtime()->initialFrame($p['public'],$f['token']);pe_assert(isset($initial['entry'])&&!isset($initial['access'],$initial['email'],$initial['portal_view']),'Initial screen restored study identity');
});
pf_case('Corrected email remains pending until link and preserves first answer execution and identity',function(){
 list($p,$f,$first)=pi_confirmation();$old=pf_participant($f);$r=pi_request($p,$f,'CORRECTED@example.test');pe_assert(pf_participant($f)['email']===$old['email'],'Updated before proof');$cap=pi_mail_cap($r);$mail=end($GLOBALS['m0_mail']);pe_assert(in_array('corrected@example.test',(array)$mail['to'],true),'Wrong recipient');$done=pf_runtime()->redeem($p['public'],$cap);$now=pf_participant($done);pe_assert($now['email']==='corrected@example.test'&&$now['verification_state']==='VERIFIED'&&$now['id']===$old['id']&&$done['access']['execution_id']===$f['access']['execution_id'],'Identity replaced');pe_assert($done['view']['snapshot']['instances'][$first]['state']==='COMPLETED'&&count((new P\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id']))===1,'First response lost');pe_assert(L\EmailConfirmation::read(pf_db(),$f['access']['execution_id'])['state']==='CONFIRMED','Not confirmed');pe_assert((new L\Identity(pf_db(),pf_clock()))->recover($p['public'],$f['token'])===null,'Old browser session survives identity change');
});
pf_case('Correction request is idempotent and newer address invalidates earlier links',function(){
 list($p,$f)=pi_confirmation();$oldCap=pf_mint($f,'VERIFY_PARTICIPANT');$r=pi_request($p,$f,'first-correction@example.test','CORRECTION_ONE');$cap=pi_mail_cap($r);$count=count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'));pi_request($p,$r,'first-correction@example.test','CORRECTION_ONE');pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===$count,'Duplicate correction');$r=pi_request($p,$r,'second-correction@example.test','CORRECTION_TWO');pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');pe_reject(function()use($p,$oldCap){pf_runtime()->redeem($p['public'],$oldCap);},'ACCESS_REQUIRED');$done=pf_runtime()->redeem($p['public'],pi_mail_cap($r));pe_assert(pf_participant($done)['email']==='second-correction@example.test','Wrong correction accepted');
});
pf_case('Email already belonging to another participant cannot merge or replace identities',function(){
 list($p,$f)=pi_confirmation();$other=pf_enroll($p,'taken-confirmation@example.test');$before=pf_participant($f);pe_reject(function()use($p,$f){pi_request($p,$f,'taken-confirmation@example.test');},'EMAIL_ALREADY_ENROLLED');pe_assert(pf_participant($f)['email']===$before['email']&&pf_participant($other)['id']!==$before['id']&&L\EmailConfirmation::read(pf_db(),$f['access']['execution_id'])===null,'Merged identities');
});
pf_case('Single-assessment completion remains pending confirmation then returns to finished state',function(){
 list($p,$f)=pi_confirmation(null);pe_assert($f['view']['next_action']['kind']==='EMAIL_CONFIRMATION_REQUIRED','Final bypass');$r=pi_request($p,$f,pf_participant($f)['email']);$done=pf_runtime()->redeem($p['public'],pi_mail_cap($r));pe_assert($done['view']['next_action']['kind']==='FINISHED','Completion reopened');
});
pf_case('Second-opportunity policy accepts corrected confirmation as verification without extra link',function(){
 $saved=$GLOBALS['pf_now'];try{list($p,$f)=pi_confirmation('03','AFTER_FIRST');$r=pi_request($p,$f,'second-stage@example.test');$done=pf_runtime()->redeem($p['public'],pi_mail_cap($r));$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+86400);$next=pf_runtime()->handle($p['public'],$done['token']);pe_assert($next['view']['next_action']['kind']==='OPEN_ASSESSMENT'&&pf_participant($next)['verification_state']==='VERIFIED','Extra verification demanded');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('Verification anchored first assessment always has an initial verification email',function(){
 $c=pf_initial_v1();$c['authentication']['verification']='IMMEDIATE';$d=L\Configuration::apply(pe_definition(),array('initial_screen'=>$c));foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT'){$n['schedule']['anchor']='PARTICIPANT_VERIFIED';$n['schedule']['anchor_ref']=null;$n['schedule']['occurrence_selector']=null;}unset($n);$p=pe_publish('simple',false,$d);$f=pf_enroll($p);$intents=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($intents)===1&&$intents[0]['block_execution_id']===null,'Verification deadlock');$cap=pf_mint($f,'VERIFY_PARTICIPANT');$done=pf_runtime()->redeem($p['public'],$cap);pe_assert($done['view']['next_action']['kind']==='OPEN_ASSESSMENT','Anchor not resolved');
});
pf_case('HTTP first submit correction email confirmation returns finished with same stored response',function(){
 $old=$GLOBALS['pf_now'];try{$c=pf_initial_v1();$c['authentication']['confirm_after_first']=true;list($p,$h,$cookies)=pf_http_enroll(null,array('initial_screen'=>$c));$first=pf_http_finish_native($p,$h,$cookies,array('R_q1'=>'Respuesta HTTP conservada'));pe_assert($first['status']===200&&$first['data']['state']==='EMAIL_CONFIRMATION_REQUIRED','No HTTP confirmation step');$request=pe_http_request($first,'confirm_email');$request['email']='http-corrected@example.test';$pending=pf_http($p['public'],$cookies,$request);pe_assert($pending['status']===200&&$pending['data']['state']==='EMAIL_CONFIRMATION_REQUIRED','No pending HTTP');$frame=pf_http_frame($p,$pending,$cookies);$GLOBALS['pf_now']=(new L\Clock())->now();$cap=pi_mail_cap($frame);$exchange=pf_http($p['public'],array(),null,$cap);pe_assert($exchange['status']===303,'No confirmation exchange');$done=pf_http($p['public'],$exchange['cookies']);pe_assert($done['status']===200&&$done['data']['state']==='EMAIL_ENTRY'&&strpos($done['data']['html'],'data-notice="finished_body"')===false,'Cookie restored a completed study');$participant=(new L\Identity(pf_db(),new L\Clock()))->participant($frame['access']['participant_id']);pe_assert($participant['email']==='http-corrected@example.test'&&$participant['verification_state']==='VERIFIED','HTTP identity not corrected');pe_assert(count((new P\SubmissionJournalRepository(pf_db()))->list($frame['access']['execution_id']))===1,'HTTP response lost');}finally{$GLOBALS['pf_now']=$old;}
});
pf_case('Post-first confirmation cannot be bypassed via native endpoint or invalid CSRF',function(){
 $previousNow=$GLOBALS['pf_now'];$GLOBALS['pf_now']=(new L\Clock())->now();
 try {
 list($p,$f)=pi_confirmation();$name=L\Identity::cookieName($p['public']);$old=$_COOKIE[$name]??null;$_COOKIE[$name]=$f['token'];try{$binding=array('kind'=>'STUDY_SESSION','public_id'=>$p['public'],'execution_id'=>$f['access']['execution_id'],'participant_id'=>$f['access']['participant_id'],'study_version_id'=>$f['access']['study_version_id']);pe_reject(function()use($binding){pf_db()->transactional(function()use($binding){EIPSI\AssessmentEditor\Runtime\Authorization::check(new EIPSI\AssessmentEditor\Runtime\Store(),$binding);});},'Confirmá tu email después');pe_reject(function()use($p,$f){pf_runtime()->handle($p['public'],$f['token'],array('action'=>'confirm_email','command_id'=>'BAD_EMAIL_CSRF','csrf'=>'wrong','expected_revision'=>$f['view']['revision'],'email'=>'csrf-correction@example.test'));},'CSRF_REJECTED');pe_assert(L\EmailConfirmation::read(pf_db(),$f['access']['execution_id'])===null,'CSRF changed identity');}finally{if($old===null)unset($_COOKIE[$name]);else $_COOKIE[$name]=$old;}
 } finally {$GLOBALS['pf_now']=$previousNow;}
