pf_case('Verification resend from valid provisional session creates email and preserves future opportunity intents',function(){
 $c=pf_initial_v1();$c['authentication']['verification']='IMMEDIATE';$p=pf_publish('04',array('initial_screen'=>$c,'email_enabled'=>false));$f=pf_enroll($p);$old=pf_mint($f,'VERIFY_PARTICIPANT');$r=pf_runtime()->handle($p['public'],$f['token'],array('action'=>'resend','command_id'=>'RESEND_PROVISIONAL','csrf'=>$f['csrf'],'email'=>pf_participant($f)['email']));$rows=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');$future=array_values(array_filter($rows,static function($i){return $i['block_execution_id']!==null&&$i['state']==='PENDING';}));$auth=array_values(array_filter($rows,static function($i){return $i['block_execution_id']===null;}));pe_assert(count($future)===7&&count($auth)===1,'Resend lost future verification or skipped email');pe_assert(pf_delivery($auth[0])['success'],'Resend not delivered');pe_reject(function()use($p,$old){pf_runtime()->redeem($p['public'],$old);},'ACCESS_REQUIRED');
});

require __DIR__.'/verification-v2.php';
pf_case('Withdrawal rich title colors and typed confirmation are pinned and enforced',function(){
 $c=L\InitialScreen::defaults();$c['withdrawal']['typed_confirmation']=true;$c['withdrawal']['modal_title_html']='<strong>Mi decisión</strong><script>alert(1)</script>';$c['withdrawal']['retain_label']='Conservar datos';$c['withdrawal']['delete_label']='Eliminar datos';$c['withdrawal']['retain_background']='#123456';$c=L\InitialScreen::normalize($c);pe_assert(strpos($c['withdrawal']['modal_title_html'],'<script')===false,'Unsafe title');$p=pf_publish(null,array('initial_screen'=>$c));$html=(new L\EmailTemplate())->screen(pf_runtime()->handle($p['public']));pe_assert(strpos($html,'<strong>Mi decisión</strong>')!==false&&strpos($html,'background:#123456')!==false&&strpos($html,'data-withdrawal-choice="RETAIN_FOR_ANALYSIS"')!==false,'Missing presentation');$f=pf_enroll($p,'typed-withdraw@example.test');$shell=pf_runtime()->redeem($p['public'],pf_mint($f,'WITHDRAWAL_OPTIONS'));$req=array('action'=>'withdraw','command_id'=>'TYPED_WITHDRAW','email'=>'typed-withdraw@example.test','csrf'=>$shell['csrf'],'mode'=>'RETAIN_FOR_ANALYSIS','expected_revision'=>$shell['view']['revision']);pe_reject(function()use($p,$shell,$req){pf_runtime()->handle($p['public'],$shell['token'],$req);},'WITHDRAWAL_CONFIRMATION_REQUIRED');$req['confirmation_text']='conservar datos';pe_reject(function()use($p,$shell,$req){pf_runtime()->handle($p['public'],$shell['token'],$req);},'WITHDRAWAL_CONFIRMATION_REQUIRED');pe_assert(pf_participant($f)['privacy_state']==='ACTIVE','Premature withdrawal');$req['confirmation_text']='CONSERVAR DATOS';$done=pf_runtime()->handle($p['public'],$shell['token'],$req);pe_assert($done['withdrawal']['mode']==='RETAIN_FOR_ANALYSIS','Valid confirmation failed');
});

pf_case('Button design validates styles and renders hover and parallel choices',function(){
 $c=L\InitialScreen::defaults();$c['withdrawal']['typed_confirmation']=true;$c['withdrawal']['choices_layout']='ROW';$c['button_styles']=array('continue'=>array('background'=>'#123456','hover_background'=>'#654321','border_width'=>3,'radius'=>12,'font_size'=>18),'delete'=>array('hover_text_color'=>'#ffffff'));$c=L\InitialScreen::normalize($c);$p=pf_publish(null,array('initial_screen'=>$c));$html=(new L\EmailTemplate())->screen(pf_runtime()->handle($p['public']));pe_assert(strpos($html,'eipsi-withdrawal-choices is-parallel')!==false&&strpos($html,'--eipsi-button-hover-background:#654321')!==false&&strpos($html,'--eipsi-button-border-width:3px')!==false,'Button styles not rendered');$bad=$c;$bad['button_styles']['continue']['background']='red;display:none';pe_reject(function()use($bad){L\InitialScreen::normalize($bad);},'INVALID_INITIAL_COLOR');$bad=$c;$bad['button_styles']['continue']['font_size']=200;pe_reject(function()use($bad){L\InitialScreen::normalize($bad);},'INVALID_BUTTON_STYLE');$bad=$c;$bad['withdrawal']['choices_layout']='INVALID';pe_reject(function()use($bad){L\InitialScreen::normalize($bad);},'INVALID_WITHDRAWAL_LAYOUT');
});

pf_case('Confirmation presentation is sanitized and preserves a mandatory generated phrase',function(){
 $c=L\InitialScreen::defaults();$c['withdrawal']['typed_confirmation']=true;$c['withdrawal']['confirmation']=array_merge(L\InitialScreen::confirmationDefaults(),array('title_html'=>'<h2>Revisar decisión</h2><script>alert(1)</script>','body_html'=>'<p>Elegiste <em>[OPCION]</em>. Escribí <strong>[CONFIRMACION]</strong>.</p>','input_label'=>'Tu decisión','cancel_label'=>'Volver al estudio','background'=>'#abcdef','buttons_layout'=>'COLUMN'));$c['max_width']=880;$c['withdrawal']['confirmation']['max_width']=400;$c['button_styles']=array('confirm'=>array('background'=>'#edf3fa'));$c=L\InitialScreen::normalize($c);$p=pf_publish(null,array('initial_screen'=>$c));$f=pf_enroll($p,'confirmation-format@example.test');$shell=pf_runtime()->redeem($p['public'],pf_mint($f,'WITHDRAWAL_OPTIONS'));$html=(new L\EmailTemplate())->screen($shell);pe_assert(strpos($html,'<script')===false&&strpos($html,'Revisar decisión')!==false&&strpos($html,'Volver al estudio')!==false&&strpos($html,'data-confirm-phrase-display')!==false&&strpos($html,'background:#abcdef')!==false,'Confirmation presentation missing');pe_assert(strpos($html,'<em><span data-confirm-description></span></em>')!==false&&strpos($html,'<strong><span data-confirm-phrase-display></span></strong>')!==false&&strpos($html,'<label>Texto de confirmación')===false,'Variable formatting or hidden label');pe_assert(substr_count($html,'width:min(880px,calc(100vw - 40px))')===2,'Modal widths differ from Initial Screen');pe_assert(strpos(L\InitialScreen::buttonStyle($c,'confirm'),'--eipsi-button-hover-background:#c9cfd5')!==false,'Default hover does not change');$bad=$c;$bad['withdrawal']['confirmation']['background']='red;display:none';pe_reject(function()use($bad){L\InitialScreen::normalize($bad);},'INVALID_INITIAL_COLOR');
});
